const ScriptDef& scriptDef(ScriptId id) {
    return kDefs[static_cast<int>(id)];
}

bool findScript(const char* name, ScriptId* out) {
    for (int i = 0; i < static_cast<int>(ScriptId::Count); i++) {
        if (!strcmp(kDefs[i].name, name)) {
            *out = static_cast<ScriptId>(i);
            return true;
        }
    }
    return false;
}

const char* scriptOpName(ScriptOp op) {
    return kOpNames[static_cast<int>(op)];
}

const char* scriptVarName(ScriptVar v) {
    return kVarNames[static_cast<int>(v)];
}

